#include <stdio.h>
int findComplement(int num) {
    unsigned int x = (unsigned int)num, mask = 0;
    while (x > 0) { mask = (mask << 1) | 1u; x >>= 1; }
    return (int)(((unsigned int)num) ^ mask);
}

